-- ADHD push sender, Cloudflare D1. Apply with: wrangler d1 execute adhd-push --file=schema.sql
-- No accounts: an "install" is a random id + secret generated by one browser; only SHA-256(secret) is stored.
CREATE TABLE IF NOT EXISTS installs (
  id TEXT PRIMARY KEY, secret_hash TEXT NOT NULL, created_at INTEGER NOT NULL, last_seen INTEGER NOT NULL);

CREATE TABLE IF NOT EXISTS subs (
  install_id TEXT PRIMARY KEY REFERENCES installs(id), endpoint TEXT NOT NULL, p256dh TEXT NOT NULL, auth TEXT NOT NULL,
  created_at INTEGER NOT NULL, retired_at INTEGER);

CREATE TABLE IF NOT EXISTS schedules (
  id TEXT PRIMARY KEY, install_id TEXT NOT NULL REFERENCES installs(id),
  time TEXT NOT NULL, tz TEXT NOT NULL, recur TEXT NOT NULL,           -- 'once' | 'daily' | 'weekdays'
  label TEXT NOT NULL DEFAULT '', followups INTEGER NOT NULL DEFAULT 0, tandem INTEGER NOT NULL DEFAULT 0,
  revision INTEGER NOT NULL DEFAULT 1, enabled INTEGER NOT NULL DEFAULT 1, next_due INTEGER,
  created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS schedules_due ON schedules(enabled, next_due);

-- id = "<scheduleId>:<dueMs>", so materialising the same due time twice is a no-op (idempotent).
CREATE TABLE IF NOT EXISTS occurrences (
  id TEXT PRIMARY KEY, schedule_id TEXT NOT NULL, install_id TEXT NOT NULL, due INTEGER NOT NULL,
  status TEXT NOT NULL,                                                  -- ACTIVE | COMPLETED | CANCELLED | MISSED
  reason TEXT, label TEXT NOT NULL DEFAULT '', followups INTEGER NOT NULL DEFAULT 0, tandem INTEGER NOT NULL DEFAULT 0,
  gen INTEGER NOT NULL DEFAULT 0,                                        -- cancellation generation: bumped on every terminal change
  paused_until INTEGER NOT NULL DEFAULT 0, acked_at INTEGER, updated_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS occurrences_active ON occurrences(status, due);

-- id = "<occurrenceId>:<stage>:<main|companion>" is the unique attempt id: one row, one send, ever.
CREATE TABLE IF NOT EXISTS attempts (
  id TEXT PRIMARY KEY, occ_id TEXT NOT NULL, install_id TEXT NOT NULL, gen INTEGER NOT NULL,
  stage INTEGER NOT NULL, kind TEXT NOT NULL,
  status TEXT NOT NULL,        -- planned | sending | sent (provider accepted) | gone | failed | cancelled | coalesced
  planned_at INTEGER NOT NULL, sent_at INTEGER, tries INTEGER NOT NULL DEFAULT 0, http_status INTEGER,
  received_at INTEGER,         -- service worker receipt (reported back by the worker)
  opened_at INTEGER);          -- user tapped the notice
CREATE INDEX IF NOT EXISTS attempts_due ON attempts(status, planned_at);
CREATE INDEX IF NOT EXISTS attempts_occ ON attempts(occ_id, sent_at);

CREATE TABLE IF NOT EXISTS rate (key TEXT NOT NULL, bucket INTEGER NOT NULL, n INTEGER NOT NULL, PRIMARY KEY (key, bucket));
